import Testing
import ColorCore
import DesignKit

// The legibility cases of `DesignTokens.standard`, recorded on macOS 27 with the system's own colours: each text and
// glyph role on each surface the kit draws it on, on the window's gradient and inside a list column, the contrast of the
// system default (before) and of the kit's colour (after), against its threshold. CHANGELOG.md (0.2.1) lists the frame
// cases against what 0.2.0 drew, 0.2.3 the column's. Regenerate with `swift run --package-path Gallery DesignKitGallery
// audit`.

/// A recorded case's placement, by name: `.column` here is not the deprecated `SurfacePlacement.column`, so the
/// recordings compile without a warning per line until 0.3 removes the column and its cases.
enum RecordedPlacement: String, Sendable {
    case frame, column
}

struct RecordedCase: Sendable, CustomTestStringConvertible {
    let theme: String
    let appearance: Appearance
    let placement: SurfacePlacement
    let role: LegibilityCase.Role
    let surface: LegibilityCase.SurfaceKind
    let before: Double
    let after: Double
    let threshold: Double

    init(
        _ theme: String, _ appearance: Appearance, _ role: LegibilityCase.Role, _ surface: LegibilityCase.SurfaceKind,
        in placement: RecordedPlacement = .frame, before: Double, after: Double, threshold: Double
    ) {
        self.theme = theme
        self.appearance = appearance
        self.placement = SurfacePlacement(rawValue: placement.rawValue)!
        self.role = role
        self.surface = surface
        self.before = before
        self.after = after
        self.threshold = threshold
    }

    var key: String { "\(theme) \(appearance) \(placement) \(role) \(surface)" }
    var testDescription: String {
        "\(theme) \(appearance) \(role.rawValue) on \(surface.rawValue)\(placement == .frame ? "" : " in the column")"
    }

